"use client";
import { ArtemisScope } from "./artemis-scope";
import type { ArtemisFaqContent } from "./components/faq-blocks/content";
import View3 from "./components/faq-blocks/variants/04-split";
const variants = {"split":View3};
export type { ArtemisFaqContact, ArtemisFaqContent, ArtemisFaqLink, ArtemisFaqQuestion, ArtemisFaqSearch } from "./components/faq-blocks/content";
export interface ArtemisFaqBlocksProps { className?: string; variant?: "split"; /** The words on the FAQ section; anything left out keeps the layout's own copy. */ content?: Partial<ArtemisFaqContent>; }
export function ArtemisFaqBlocks({ className, variant = "split", content }: ArtemisFaqBlocksProps) {const View = variants[variant];return <ArtemisScope className={className}><div className="art:flex art:w-full art:min-w-0 art:flex-col art:items-center"><View content={content}/></div></ArtemisScope>;}

// @zeus-internal

/** The words on a button or link, and where it goes. */
export interface ArtemisFaqLink {
  label: string;
  href: string;
}

/** A question and its answer. */
export interface ArtemisFaqQuestion {
  /** The question, on the row that opens. */
  question: string;
  /** The answer, shown while the row is open. */
  answer: string;
  /** A short slug, unique in the list, used in the row's element ids. Defaults to the row's position. */
  id?: string;
  /** The topic it belongs to. search shows it on the row and adds a filter tab for each topic, in the order the topics first appear; with no topics it shows no tabs. */
  category?: string;
}

/** A card beside the questions that points to a person. */
export interface ArtemisFaqContact {
  /** A small line over the title. split. */
  label?: string;
  /** The card's heading. */
  title: string;
  /** The paragraph under the heading. */
  description: string;
  /** The card's button. */
  cta: ArtemisFaqLink;
}

/** The words on the search box, its topic tabs and its empty result. */
export interface ArtemisFaqSearch {
  /** The hint in the empty search box. */
  placeholder: string;
  /** The first topic tab, which shows every question. */
  allLabel: string;
  /** The heading shown when no question matches. */
  emptyTitle: string;
  /** The line under that heading. */
  emptyText: string;
}

/** The words on an Artemis FAQ section. Every layout reads this shape, so you can switch layouts and keep them. */
export interface ArtemisFaqContent {
  /** The short line above the heading. All layouts. */
  badge: string;
  /** The heading. All layouts. */
  headline: string;
  /** The heading's last words. stacked underlines them; the other layouts run them on after `headline`. Left out, it keeps the layout's own only when `headline` is left out too. */
  headlineAccent?: string;
  /** The paragraph under the heading. All layouts. */
  subhead: string;
  /** The questions, each opening to show its answer. All layouts. numbered and split number them; numbered, ai-workspace, split and search open one at a time, starting with the first; stacked opens any number, starting with the first two. */
  questions: ArtemisFaqQuestion[];
  /** A card with a button beside the questions. ai-workspace and split. */
  contact?: ArtemisFaqContact;
  /** The words on the search box, the topic tabs and the empty result. search. */
  search?: ArtemisFaqSearch;
}

"use client";
// @zeus-internal
import { useId, useState } from "react";
import { motion, useReducedMotion } from "motion/react";
import { ArtemisButton } from "../../../foundations/button";
import { ARTEMIS_EASE_OUT, ARTEMIS_EASE_OUT_CSS, ARTEMIS_SPRING_PRESS } from "../../../lib/ease";
import type { ArtemisFaqContent } from "../content";
const DEFAULT = {
    badge: "Questions, answered",
    headline: "The details, without the fine print.",
    subhead: "Everything you need to know before creating your first workspace.",
    questions: [
        { id: "trial", question: "Can I try the product before choosing a plan?", answer: "Yes. Every workspace starts with a 14-day trial, and you can explore the full product without adding a payment method." },
        { id: "invite", question: "How do I bring my team in?", answer: "Invite people by email or share a private join link. You can change roles and access at any time from workspace settings." },
        { id: "import", question: "Can I move my existing work over?", answer: "You can import common file formats or start from a template. Our support team can also help with larger moves." },
        { id: "plans", question: "What is included in each plan?", answer: "Every plan includes the core workspace. Higher plans add more guests, longer history, and organization controls for larger teams." },
        { id: "change-plan", question: "Can I change my plan later?", answer: "Anytime. Upgrades take effect immediately, while downgrades begin at the end of your current billing period." },
        { id: "annual", question: "Do you offer annual billing?", answer: "Yes. Annual plans include two months at no additional cost and use the same features and support as monthly plans." },
        { id: "ownership", question: "Who owns the content we add?", answer: "You do. Your team keeps ownership of everything it creates and can export workspace content whenever needed." },
    ],
    contact: {
        label: "Human support",
        title: "Still deciding?",
        description: "Tell us what you are comparing and we will help you choose the right setup.",
        cta: { label: "Ask a question", href: "#faq-contact" },
    },
} satisfies ArtemisFaqContent;
const hidden = { opacity: 0, filter: "blur(8px)", y: 18 };
const shown = { opacity: 1, filter: "blur(0px)", y: 0 };
export default function FaqBlocksSplit({ content }: { content?: Partial<ArtemisFaqContent> } = {}) {
    const copy = { ...DEFAULT, ...content };
    const baseId = useId();
    const reduce = useReducedMotion();
    const [active, setActive] = useState<number | null>(0);
    return (<section className="art:w-full art:bg-background art:px-4 art:py-16 art:text-foreground art:@min-[640px]/artemis:px-8 art:@min-[640px]/artemis:py-24">
      <div className="art:mx-auto art:grid art:w-full art:max-w-6xl art:gap-12 art:@min-[1024px]/artemis:grid-cols-[0.9fr_1.1fr] art:@min-[1024px]/artemis:gap-16">
        <motion.div className="art:@min-[1024px]/artemis:sticky art:@min-[1024px]/artemis:top-8 art:@min-[1024px]/artemis:self-start" initial={hidden} animate={shown} transition={reduce ? { duration: 0 } : { duration: 0.55, ease: ARTEMIS_EASE_OUT, delay: 0.05 }}>
          <p className="art:font-medium art:text-muted-foreground art:text-sm">{copy.badge}</p>
          <h2 className="art:mt-4 art:max-w-md art:text-balance art:font-medium art:text-4xl art:leading-none art:tracking-tight">{copy.headlineAccent ? `${copy.headline} ${copy.headlineAccent}` : copy.headline}</h2>
          <p className="art:mt-5 art:max-w-md art:text-pretty art:text-muted-foreground art:text-sm art:leading-6">{copy.subhead}</p>
          <div className="art:mt-10 art:max-w-md art:rounded-2xl art:border art:border-border art:bg-background art:p-5 art:@min-[640px]/artemis:p-6">
            <div className="art:flex art:items-center art:gap-3">
              <span className="art:grid art:size-10 art:shrink-0 art:place-items-center art:rounded-full art:border art:border-border art:bg-background art:text-muted-foreground">
                <svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" className="art:lucide art:lucide-message-circle art:size-4" aria-hidden="true">
                  <path d="M2.992 16.342a2 2 0 0 1 .094 1.167l-1.065 3.29a1 1 0 0 0 1.236 1.168l3.413-.998a2 2 0 0 1 1.099.092 10 10 0 1 0-4.777-4.719"/>
                </svg>
              </span>
              <div>
                {copy.contact.label ? <p className="art:font-medium art:text-muted-foreground art:text-xs art:uppercase art:tracking-[0.14em]">{copy.contact.label}</p> : null}
                <p className="art:mt-1 art:font-medium art:text-xl">{copy.contact.title}</p>
              </div>
            </div>
            <p className="art:mt-4 art:max-w-sm art:text-pretty art:text-muted-foreground art:text-sm art:leading-6">{copy.contact.description}</p>
            <motion.a whileHover={reduce ? undefined : { scale: 1.01 }} whileTap={reduce ? undefined : { scale: 0.99 }} transition={ARTEMIS_SPRING_PRESS} className="art:inline-flex art:items-center art:justify-center art:font-medium art:select-none art:transition-colors art:disabled:pointer-events-none art:disabled:opacity-50 art:border art:border-border art:text-foreground art:hover:bg-primary/5 art:gap-1.5 art:text-xs art:focus-visible:outline-none art:focus-visible:ring-2 art:focus-visible:ring-ring art:focus-visible:ring-offset-2 art:focus-visible:ring-offset-background art:mt-5 art:bg-background art:px-4 art:h-9 art:rounded-full" href={copy.contact.cta.href} tabIndex={0}>
              {copy.contact.cta.label}
              <svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" className="art:lucide art:lucide-arrow-up-right art:size-4" aria-hidden="true"><path d="M7 7h10v10"/><path d="M7 17 17 7"/></svg>
            </motion.a>
          </div>
        </motion.div>
        <motion.div initial={hidden} animate={shown} transition={reduce ? { duration: 0 } : { duration: 0.55, ease: ARTEMIS_EASE_OUT, delay: 0.15 }}>
          <div className="art:border-border art:border-t">
            {copy.questions.map((item, index) => {
            const id = item.id ?? `q${index}`;
            const open = active === index;
            const triggerId = `${baseId}-${id}-trigger`;
            const contentId = `${baseId}-${id}-content`;
            return (<motion.div layout="position" key={id} className="art:border-border art:border-b art:has-[:focus-visible]:ring-2 art:has-[:focus-visible]:ring-foreground art:has-[:focus-visible]:ring-inset" initial={hidden} animate={shown} transition={reduce ? { duration: 0 } : { duration: 0.55, ease: ARTEMIS_EASE_OUT, delay: 0.18 + index * 0.065 }}>
                  <ArtemisButton variant="link" size="none" type="button" className="art:justify-center art:select-none art:transition-colors art:disabled:pointer-events-none art:disabled:opacity-50 art:text-sm art:focus-visible:ring-ring art:focus-visible:ring-offset-background art:h-auto art:p-0 art:font-normal art:text-inherit art:hover:bg-transparent art:hover:text-inherit art:group art:flex art:min-h-16 art:w-full art:items-start art:gap-4 art:py-5 art:text-left art:focus-visible:outline-none art:focus-visible:ring-0 art:focus-visible:ring-offset-0 art:@min-[640px]/artemis:min-h-20 art:@min-[640px]/artemis:py-6 art:rounded-full" id={triggerId} aria-expanded={open} aria-controls={contentId} tabIndex={0} onClick={() => setActive(open ? null : index)} whileTap={reduce ? undefined : { scale: 0.99 }}>
                    <span className="art:mt-1 art:w-8 art:shrink-0 art:font-medium art:text-muted-foreground art:text-xs art:tabular-nums">{String(index + 1).padStart(2, "0")}</span>
                    <span className="art:min-w-0 art:flex-1 art:font-medium art:text-xl art:leading-7">{item.question}</span>
                    <span aria-hidden="true" className="art:mt-0.5 art:grid art:size-8 art:shrink-0 art:place-items-center art:rounded-full art:bg-muted art:text-muted-foreground art:transition-colors art:duration-200 art:group-hover:bg-foreground/10 art:group-hover:text-foreground">
                      {open ? <svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" className="art:lucide art:lucide-minus art:size-4" aria-hidden="true"><path d="M5 12h14"/></svg> : <svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" className="art:lucide art:lucide-plus art:size-4" aria-hidden="true"><path d="M5 12h14"/><path d="M12 5v14"/></svg>}
                    </span>
                  </ArtemisButton>
                  <section id={contentId} aria-labelledby={triggerId} aria-hidden={!open} style={{ transitionTimingFunction: ARTEMIS_EASE_OUT_CSS }} className={`art:grid art:overflow-hidden art:transition-[grid-template-rows] art:duration-300 art:motion-reduce:transition-none ${open ? "art:grid-rows-[1fr]" : "art:grid-rows-[0fr]"}`}>
                    <div className="art:min-h-0 art:overflow-hidden">
                      <div style={{ transitionTimingFunction: ARTEMIS_EASE_OUT_CSS }} className={`art:max-w-2xl art:text-pretty art:text-muted-foreground art:text-sm art:leading-6 art:transition-[opacity,transform] art:duration-200 art:motion-reduce:transition-none ${open ? "art:translate-y-0 art:opacity-100" : "art:-translate-y-1 art:opacity-0"} art:pl-12`}>
                        <div className="art:pb-6 art:@min-[640px]/artemis:pb-7">{item.answer}</div>
                      </div>
                    </div>
                  </section>
                </motion.div>);
        })}
          </div>
        </motion.div>
      </div>
      <span id="faq-contact" className="art:sr-only">{"Contact support"}</span>
    </section>);
}
